-- Dữ liệu mẫu cho CSDL banvemaybay, theo đúng nghiệp vụ bán vé:
--  * Giá vé = giá chuyến bay (hạng Phổ thông) x hệ số hạng vé, làm tròn nghìn đồng.
--  * Mỗi máy bay có sơ đồ ghế đầy đủ; tổng ghế của chuyến = số ghế của máy bay.
--  * Vé thuộc 1 phiếu đặt; hành khách là người thuộc khách hàng đặt; 1 hành khách 1 vé / chuyến.
--  * Mỗi phiếu đặt đã thanh toán có đúng 1 hóa đơn; mỗi vé có đúng 1 dòng chi tiết, SL = 1.
--  * HD01-HD20 rải từ quý 2/2025 đến quý 4/2026; DV21, DV22 đang chờ thanh toán (chưa có hóa đơn).
-- Số dòng: HoaDon 20, ChiTietHoaDon 30, Ve 33, DatVe 22, HanhKhach 20, HangVe 3, Ghe 1508, các bảng khác 10.
-- Cách dùng: chạy BanVeMayBay.sql để tạo bảng trước, rồi Import file này vào CSDL banvemaybay.

SET NAMES utf8mb4;


















-- Các field do chương trình tự tính
UPDATE ChuyenBay c SET TongSoGhe = (SELECT COUNT(*) FROM Ghe g WHERE g.MaMayBay = c.MaMayBay);
UPDATE ChuyenBay c SET SoVeDaBan = (SELECT COUNT(*) FROM Ve v WHERE v.MaChuyenBay = c.MaChuyenBay AND v.TrangThai <> 'Đã hủy');
UPDATE DatVe d SET TongTien = GREATEST((SELECT COALESCE(SUM(v.DonGiaVe), 0) FROM Ve v WHERE v.MaDV = d.MaDV AND v.TrangThai <> 'Đã hủy') - d.GiamGia, 0);
UPDATE HoaDon h SET TongTien = GREATEST(
  COALESCE((SELECT SUM(c.ThanhTien) FROM ChiTietHoaDon c WHERE c.MaHD = h.MaHD), 0)
  - (SELECT d.GiamGia FROM DatVe d WHERE d.MaDV = h.MaDV), 0);
